 1→---
 2→apiVersion: elasticsearch.k8s.elastic.co/v1
 3→kind: Elasticsearch
 4→metadata:
 5→  name: {{ include "elasticsearch.fullname" . }}
 6→  labels:
 7→    {{- include "elasticsearch.labels" . | nindent 4 }}
 8→  annotations:
 9→    eck.k8s.elastic.co/license: basic
10→    {{- with .Values.annotations }}
11→    {{- toYaml . | nindent 4 }}
12→    {{- end }}
13→spec:
14→  {{- with .Values.auth }}
15→  auth:
16→    {{- toYaml . | nindent 4 }}
17→  {{- end }}
18→  {{- with .Values.updateStrategy }}
19→  updateStrategy:
20→    {{- toYaml . | nindent 4 }}
21→  {{- end }}
22→  {{- with .Values.secureSettings }}
23→  secureSettings:
24→    {{- toYaml . | nindent 2 }}
25→  {{- end }}
26→  {{- with .Values.transport }}
27→  transport:
28→    {{- toYaml . | nindent 4 }}
29→  {{- end }}
30→  {{- with .Values.http }}
31→  http:
32→    {{- toYaml . | nindent 4 }}
33→  {{- end }}
34→  version: {{ required "An Elasticsearch version is required" .Values.version }}
35→  {{- with .Values.monitoring }}
36→  monitoring:
37→    {{- toYaml . | nindent 4 }}
38→  {{- end }}
39→  {{- with .Values.remoteClusters }}
40→  remoteClusters:
41→    {{- toYaml . | nindent 2 }}
42→  {{- end }}
43→  {{- with .Values.remoteClusterServer }}
44→  remoteClusterServer:
45→    {{- toYaml . | nindent 4 }}
46→  {{- end }}
47→  {{- with .Values.volumeClaimDeletePolicy }}
48→  volumeClaimDeletePolicy:
49→    {{- if and (not (eq . "DeleteOnScaledownOnly")) (not (eq . "DeleteOnScaledownAndClusterDeletion")) }}
50→    {{ fail "volumeClaimDeletePolicy can only be one of 'DeleteOnScaledownOnly' or 'DeleteOnScaledownAndClusterDeletion'" }}
51→    {{- end }}
52→    {{- toYaml . | nindent 4 }}
53→  {{- end }}
54→  {{- if eq (len .Values.nodeSets) 0 }}
55→  {{ fail "At least one nodeSet is required" }}
56→  {{- end }}
57→  nodeSets:
58→    {{ toYaml .Values.nodeSets | nindent 4 }}
59→  {{- with .Values.image }}
60→  image: {{ . }}
61→  {{- end }}
62→  {{- with .Values.podDisruptionBudget }}
63→    {{- if .disabled }}
64→  podDisruptionBudget: {}
65→    {{- else }}
66→      {{- with .spec }}
67→  podDisruptionBudget:
68→    spec:
69→      {{- toYaml . | nindent 6 }}
70→      {{- end }}
71→    {{- end }}
72→  {{- end }}
73→  {{- with .Values.serviceAccountName }}
74→  serviceAccountName: {{ . }}
75→  {{- end }}
76→  {{- with .Values.revisionHistoryLimit }}
77→  revisionHistoryLimit: {{ . }}
78→  {{- end }}
79→

 1→---
 2→{{- $metricsPort := int (include "eck-operator.metrics.port" .)}}
 3→apiVersion: apps/v1
 4→kind: StatefulSet
 5→metadata:
 6→  name: {{ include "eck-operator.fullname" . }}
 7→  namespace: {{ .Release.Namespace }}
 8→  {{- with .Values.statefulsetAnnotations }}
 9→  annotations:
10→    {{- toYaml . | nindent 4 }}
11→  {{- end }}
12→  labels:
13→    {{- include "eck-operator.labels" . | nindent 4 }}
14→    {{- with .Values.statefulsetLabels }}
15→    {{- toYaml . | nindent 4 }}
16→    {{- end }}
17→spec:
18→  selector:
19→    matchLabels:
20→      {{- include "eck-operator.selectorLabels" . | nindent 6 }}
21→  serviceName: {{ include "eck-operator.fullname" . }}
22→  replicas: {{ .Values.replicaCount }}
23→  template:
24→    metadata:
25→      annotations:
26→        # Rename the fields "error" to "error.message" and "source" to "event.source"
27→        # This is to avoid a conflict with the ECS "error" and "source" documents.
28→        "co.elastic.logs/raw": "[{\"type\":\"filestream\",\"enabled\":true,\"id\":\"eck-container-logs-${data.kubernetes.container.id}\",\"paths\":[\"/var/log/containers/*${data.kubernetes.container.id}.log\"],\"parsers\":[{\"container\":{}},{\"ndjson\":{\"keys_under_root\":true}}],\"prospector.scanner.symlinks\":true,\"processors\":[{\"convert\":{\"mode\":\"rename\",\"ignore_missing\":true,\"fields\":[{\"from\":\"error\",\"to\":\"_error\"}]}},{\"convert\":{\"mode\":\"rename\",\"ignore_missing\":true,\"fields\":[{\"from\":\"_error\",\"to\":\"error.message\"}]}},{\"convert\":{\"mode\":\"rename\",\"ignore_missing\":true,\"fields\":[{\"from\":\"source\",\"to\":\"_source\"}]}},{\"convert\":{\"mode\":\"rename\",\"ignore_missing\":true,\"fields\":[{\"from\":\"_source\",\"to\":\"event.source\"}]}}]}]" 
29→        "checksum/config": {{ include (print $.Template.BasePath "/configmap.yaml") . | sha256sum }}
30→        {{- with .Values.podAnnotations }}
31→        {{- toYaml . | nindent 8 }}
32→        {{- end }}
33→      labels:
34→        {{- include "eck-operator.selectorLabels" . | nindent 8 }}
35→        {{- with .Values.podLabels }}
36→        {{- toYaml . | nindent 8 }}
37→        {{- end }}
38→    spec:
39→      terminationGracePeriodSeconds: 10
40→      serviceAccountName: {{ include "eck-operator.serviceAccountName" . }}
41→      automountServiceAccountToken: {{ .Values.automountServiceAccountToken }}
42→      {{- with .Values.priorityClassName }}
43→      priorityClassName: {{ . }}
44→      {{- end }}
45→      {{- with .Values.podSecurityContext }}
46→      securityContext:
47→        {{- toYaml . | nindent 8 }}
48→      {{- end }}
49→      {{- with .Values.imagePullSecrets }}
50→      imagePullSecrets:

 1→{{- if (and .Values.global.manifestGen .Values.global.createOperatorNamespace) -}}
